object.script:
function onTick() local p = input.getNumber(1)
local A = p > 0 and p < 21 local B = p == 21 local C = p > 21 and p < 39 local D = p == 39 local E = p > 39
local o = { A or B or C or D or E, B or C or D or E, D or E, E, A or B or C or D or E, C or D or E, D or E, E, A or B or C or D or E, C or D or E, D or E, E, A or B or C or D or E, B or C or D or E, D or E, E }
for i = 1, 16 do output.setBool(i, o[i]) end end

function onTick() local p = input.getNumber(1)
local A = p > 0 and p < 21 local B = p == 21 local C = p > 21 and p < 39 local D = p == 39 local E = p > 39
local o = { A or B or C or D or E, B or C or D or E, D or E, E, A or B or C or D or E, C or D or E, D or E, E, A or B or C or D or E, C or D or E, D or E, E, A or B or C or D or E, B or C or D or E, D or E, E }
for i = 1, 16 do output.setBool(i, o[i]) end end
